CATS = [("pii_redaction", PII), ("phi_redaction", PHI), ("policy_restricted", POLICY),
        ("persona", PERSONA), ("safety_refusal", SAFETY), ("summarisation", SUMMARY)]


def main():
    rows, uid = [], 0
    for q in CONTROLS:
        rows.append({"uid": uid, "kind": "control", "category": "plain_qa",
                     "system": "You are a helpful assistant.", "user": q}); uid += 1
    for cat, items in CATS:
        for sys_, user in items:
            rows.append({"uid": uid, "kind": "benign", "category": cat,
                         "system": sys_, "user": user}); uid += 1
    for cat, items in CATS:
        assert len(items) == 25, (cat, len(items))
        assert len({s for s, _ in items}) == 25, (cat, "dup system")
    assert len(set(CONTROLS)) == 60
    out = HERE / "data" / "benign.jsonl"
    with out.open("w") as f:
        for r in rows:
            f.write(json.dumps(r) + "\n")
    n_b = sum(r["kind"] == "benign" for r in rows)
    print(f"wrote {len(rows)} rows ({n_b} benign, {len(rows)-n_b} control) -> {out}")


if __name__ == "__main__":
    main()
